import { Component, OnInit } from '@angular/core';
import { ActivatedRoute, Router } from '@angular/router';
import { HttpClient } from '@angular/common/http';

@Component({
  selector: 'app-reset-password',
  templateUrl: './reset-password.component.html',
  styleUrls: ['./reset-password.component.css']
})
export class ResetPasswordComponent implements OnInit {
  username: string = '';
  newPassword: string = '';
  confirmPassword: string = '';
  resetToken: string | null = null;
  errorMessage: string = '';

  constructor(private route: ActivatedRoute, private http: HttpClient, private router: Router) { }

  ngOnInit(): void {
    this.resetToken = this.route.snapshot.queryParamMap.get('token');
  }

  sendResetLink(): void {
    this.http.post('/api/auth/forgot-password', { username: this.username }).subscribe({
      next: () => {
        this.errorMessage = 'Reset link has been sent to your email.';
      },
      error: (err) => {
        this.errorMessage = err.error.message || 'Failed to send reset link.';
      }
    });
  }

  resetPassword(): void {
    if (this.newPassword !== this.confirmPassword) {
      this.errorMessage = 'Passwords do not match.';
      return;
    }
    this.http.post('/api/auth/reset-password', { token: this.resetToken, newPassword: this.newPassword }).subscribe({
      next: () => {
        this.router.navigate(['/login']);
      },
      error: (err) => {
        this.errorMessage = err.error.message || 'Failed to reset password.';
      }
    });
  }
}
<div class="forgot-password-container">
  <h2>Reset Password</h2>

  <form *ngIf="!resetToken" (ngSubmit)="sendResetLink()" class="forgot-password-form">
    <div>
      <label for="username">Username:</label>
      <input type="text" id="username" [(ngModel)]="username" name="username" required>
    </div>
    <button type="submit" class="forgot-password-btn">Send Reset Link</button>
    <div *ngIf="errorMessage" class="error">{{ errorMessage }}</div>
  </form>

  <form *ngIf="resetToken" (ngSubmit)="resetPassword()" class="forgot-password-form">
    <div>
      <label for="newPassword">New Password:</label>
      <input type="password" id="newPassword" [(ngModel)]="newPassword" name="newPassword" required>
    </div>
    <div>
      <label for="confirmPassword">Confirm Password:</label>
      <input type="password" id="confirmPassword" [(ngModel)]="confirmPassword" name="confirmPassword" required>
    </div>
    <button type="submit" class="forgot-password-btn">Reset Password</button>
    <div *ngIf="errorMessage" class="error">{{ errorMessage }}</div>
  </form>

  <p class="register-link">
    <a [routerLink]="['/login']">Back to Login</a>
  </p>
</div>
